import{_ as e,o as s,c as i,a2 as l}from"./chunks/framework.DJWFW3S-.js";const c=JSON.parse('{"title":"Analysis","description":"","frontmatter":{"title":"Analysis"},"headers":[],"relativePath":"api/analysis.md","filePath":"api/analysis.md"}'),d={name:"api/analysis.md"};function t(r,a,n,o,y,m){return s(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h1><p>Analysis是三维空间分析的父类，定义了各种三维空间分析共同的方法。</p><p>Analysis只支持添加到GroupGLLayer上，无法添加到其他WebGL图层。</p><blockquote><p>注：源码中 Analysis 的子类包括 CutAnalysis（剖切）、ViewshedAnalysis（可视域）、SkylineAnalysis（天际线）、FloodAnalysis（水淹）、InSightAnalysis（通视）、CrossCutAnalysis（剖面）、HeightLimitAnalysis（限高，继承自 FloodAnalysis）。ExcavateAnalysis（挖方）不继承 Analysis，而是继承 <code>@maptalks/vt</code> 的 ExtrudePolygonLayer，不属于本页范围。</p></blockquote><h2 id="成员方法" tabindex="-1">成员方法 <a class="header-anchor" href="#成员方法" aria-label="Permalink to &quot;成员方法&quot;">​</a></h2><blockquote><p>本文档已与 maptalks-gl 0.124.4 源码核对</p></blockquote><h3 id="analysis-的其他公开方法" tabindex="-1">Analysis 的其他公开方法 <a class="header-anchor" href="#analysis-的其他公开方法" aria-label="Permalink to &quot;Analysis 的其他公开方法&quot;">​</a></h3><details><summary>addTo(layer)</summary><div><br><p>将分析添加到图层，图层就绪后创建分析 pass</p><p>参数：</p><ul><li>layer <code>Any</code></li></ul></div></details><details><summary>enable()</summary><div><br><p>启用分析并请求图层重绘</p></div></details><details><summary>disable()</summary><div><br><p>禁用分析并请求图层重绘</p></div></details><details><summary>isEnable()</summary><div><br><p>返回分析当前是否启用</p></div></details><details><summary>remove()</summary><div><br><p>从图层移除分析并销毁 pass、mesh 等资源</p></div></details><details><summary>update(name, value)</summary><div><br><p>更新指定名称的分析参数并请求重绘</p><p>参数：</p><ul><li>name <code>Any</code></li><li>value <code>Any</code></li></ul></div></details><details><summary>getExcludeLayers()</summary><div><br><p>获取不参与分析的 layer id 数组</p></div></details><details><summary>setExcludeLayers(layerIds)</summary><div><br><p>设置不参与分析的 layer id 数组</p><p>参数：</p><ul><li>layerIds <code>Any</code></li></ul></div></details><details><summary>exportAnalysisMap(meshes)</summary><div><br><p>渲染分析结果并读出 RGBA 像素数据，未启用时返回 null</p><p>参数：</p><ul><li>meshes <code>Any</code></li></ul></div></details><details><summary>getAnalysisType()</summary><div><br><p>获取分析类型标识，如 cut 或 viewshed</p></div></details><h3 id="混入的方法" tabindex="-1">混入的方法 <a class="header-anchor" href="#混入的方法" aria-label="Permalink to &quot;混入的方法&quot;">​</a></h3><p>本类通过混入获得以下能力的方法，详见对应页面：<a href="/api/eventable.html">Eventable</a>（<code>on</code>、<code>addEventListener</code>、<code>once</code>、<code>off</code>、<code>removeEventListener</code>、<code>listens</code>、<code>getListeningEvents</code>、<code>copyEventListeners</code>…）；<a href="/api/handlerable.html">Handlerable</a>。</p>',19)])])}const u=e(d,[["render",t]]);export{c as __pageData,u as default};
